                    const radarData = dims.map(d => ({ dim: dimLabels[d], ...Object.fromEntries(radarSrc.map(c => [c.name, c[d] || 5])) }));
                    const colors = ["#7A1FA2", "#0096A0", "#94A3B8", "#D97706", "#E20015"];
