                                <Radar key={c.name} name={c.name} dataKey={c.name} stroke={colors[i]} fill={colors[i]} fillOpacity={c.isBosch ? 0.2 : 0.07} strokeWidth={c.isBosch ? 2.5 : 1.5} strokeDasharray={c.isBosch ? "0" : "4 2"} />
